import React, { useCallback, useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import {
  Activity, ArrowRight, ArrowUpRight, Check, CheckCircle2, ChevronDown,
  ChevronLeft, ChevronRight, CircleHelp, Clock3, Code2, Copy, CreditCard, Database,
  Ellipsis, ExternalLink, FileText, Globe2, GitBranch, History, Home, KeyRound,
  LoaderCircle, LockKeyhole, LogOut, Menu, MessageSquare, Play, Plus,
  Search, Settings2, ShieldCheck, Sparkles, Workflow, X, Zap, AlertTriangle,
} from 'lucide-react';
import {
  addEdge, Background, BackgroundVariant, Controls, Handle, MiniMap, Position, ReactFlow,
  useEdgesState, useNodesState, type Connection, type Edge, type Node, type NodeProps,
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import './styles.css';

type User = { id: string; email: string; name: string; workspace: { id: string; name: string; role: string; plan: string } };
type FlowData = { label: string; config: Record<string, unknown> };
type FlowNode = Node<FlowData>;
type Automation = { id: string; name: string; description: string; active: boolean; version: number; definition: { nodes: FlowNode[]; edges: Edge[] }; createdAt: string; updatedAt: string; runCount: number; lastRunAt: string | null; lastRunStatus: string | null };
type Execution = { id: string; automationId: string; automationName: string; status: string; startedAt: string; finishedAt?: string; durationMs?: number; error?: string | null; steps?: Array<{ nodeId: string; label: string; type: string; status: string; durationMs: number; output?: unknown; error?: string; branch?: string }>; input?: unknown };
type ApiError = Error & { data?: any };

async function api<T = any>(path: string, init: RequestInit = {}): Promise<T> {
  const response = await fetch(path, { credentials: 'same-origin', ...init, headers: { ...(init.body ? { 'content-type': 'application/json' } : {}), ...init.headers } });
  const data = await response.json().catch(() => ({}));
  if (!response.ok) { const error = new Error(data.error || 'Ocorreu um erro.') as ApiError; error.data = data; throw error; }
  return data;
}

function go(path: string) { const navigation = new Event('autoflow:navigate', { cancelable: true }); if (!window.dispatchEvent(navigation)) return; window.history.pushState({}, '', path); window.dispatchEvent(new PopStateEvent('popstate')); }
function usePath() { const [path, setPath] = useState(window.location.pathname); useEffect(() => { const update = () => setPath(window.location.pathname); addEventListener('popstate', update); return () => removeEventListener('popstate', update); }, []); return path; }
function initials(name: string) { return name.split(/\s+/).slice(0, 2).map((part) => part[0]?.toUpperCase()).join(''); }
function dateLabel(date?: string | null) { if (!date) return 'Ainda não executado'; return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(date)); }
function durationLabel(ms?: number) { return ms == null ? '—' : ms < 1000 ? `${ms} ms` : `${(ms / 1000).toFixed(1)} s`; }

function Logo({ small = false }: { small?: boolean }) { return <div className={`brand ${small ? 'brand-small' : ''}`}><span className="brand-icon"><Workflow size={18} strokeWidth={2.4} /></span><span>auto<span className="brand-light">flow</span></span></div>; }

function App() {
  const path = usePath();
  const [user, setUser] = useState<User | null>(null);
  const [ready, setReady] = useState(false);
  const [mobileMenu, setMobileMenu] = useState(false);
  useEffect(() => { api<{ user: User | null }>('/api/auth/session').then(({ user }) => setUser(user)).catch(() => setUser(null)).finally(() => setReady(true)); }, [path === '/login' || path === '/register' || path === '/' ? path : 'private']);
  const updateUser = (value: User | null) => setUser(value);
  if (!ready) return <div className="loading-screen"><Logo /><LoaderCircle className="spin" size={20} /></div>;
  if (path === '/terms' || path === '/privacy') return <LegalPage kind={path === '/terms' ? 'terms' : 'privacy'} />;
  if (path === '/login' || path === '/register') return <AuthPage mode={path.slice(1) as 'login' | 'register'} onAuth={updateUser} />;
  if (!user && path !== '/') return <AuthPage mode="login" onAuth={updateUser} />;
  if (!user) return <Landing onStart={() => go('/register')} onLogin={() => go('/login')} />;
  const match = path.match(/^\/automations\/([\w-]+)$/);
  const selected = path === '/automations' || path.startsWith('/automations/') ? 'automations' : path === '/executions' ? 'executions' : path === '/settings' ? 'settings' : 'dashboard';
  return <AppShell user={user} selected={selected} mobileMenu={mobileMenu} setMobileMenu={setMobileMenu} onLogout={async () => { await api('/api/auth/logout', { method: 'POST', body: '{}' }).catch(() => {}); updateUser(null); go('/'); }}>
    {match ? <EditorPage key={match[1]} id={match[1]} onBack={() => go('/automations')} /> : path === '/automations' ? <AutomationsPage /> : path === '/executions' ? <ExecutionsPage /> : path === '/settings' ? <SettingsPage user={user} /> : <DashboardPage user={user} />}
  </AppShell>;
}

